{"status":"candidate","chosen_option":"coordinate-compression-fenwick","assumptions":["Use C++17 and standard input/output; the task does not specify a language.","All operations can be read before processing, so values in insertions and deletions can be coordinate-compressed."],"observations":[{"statement":"The task allows up to 200,000 operations on signed integers, with duplicates counted separately and invalid kth queries producing NONE.","source_ids":["task"]},{"statement":"The examples include a query on an empty multiset and a query with negative k; both expect NONE.","source_ids":["public1","public2"]}],"artifact":{"code":"#include <bits/stdc++.h>
using namespace std;

struct Operation {
    char type;
    long long value;
};

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n) : n(n), bit(n + 1, 0) {}
    void add(int i, long long delta) {
        for (; i <= n; i += i & -i) bit[i] += delta;
    }
    long long sum(int i) const {
        long long result = 0;
        for (; i > 0; i -= i & -i) result += bit[i];
        return result;
    }
    // Return the zero-based compressed index of the kth element (k is valid).
    int kth(long long k) const {
        int index = 0;
        int step = 1;
        while (step * 2 <= n) step *= 2;
        for (; step > 0; step /= 2) {
            int next = index + step;
            if (next <= n && bit[next] < k) {
                index = next;
                k -= bit[next];
            }
        }
        return index;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;
    vector<Operation> operations;
    vector<long long> coordinates;
    operations.reserve(q);

    for (int i = 0; i < q; ++i) {
        char type;
        long long value;
        cin >> type >> value;
        operations.push_back({type, value});
        if (type == '+' || type == '-') coordinates.push_back(value);
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()), coordinates.end());
    Fenwick fenwick(static_cast<int>(coordinates.size()));
    long long size = 0;

    for (const auto &op : operations) {
        if (op.type == '+') {
            int pos = lower_bound(coordinates.begin(), coordinates.end(), op.value) - coordinates.begin() + 1;
            fenwick.add(pos, 1);
            ++size;
        } else if (op.type == '-') {
            int pos = lower_bound(coordinates.begin(), coordinates.end(), op.value) - coordinates.begin() + 1;
            if (fenwick.sum(pos) - fenwick.sum(pos - 1) > 0) {
                fenwick.add(pos, -1);
                --size;
            }
        } else {
            long long k = op.value;
            if (k < 1 || k > size) {
                cout << "NONE\n";
            } else {
                int index = fenwick.kth(k);
                cout << coordinates[index] << '\n';
            }
        }
    }
    return 0;
}"} }
